function renderMeta() {
  const version = DATA.meta?.currentVersion || "unknown";
  document.getElementById("nav-version").textContent = version;
  document.getElementById("footer-repo").textContent = DATA.meta?.repoPath || "";
  document.getElementById("footer-time").textContent = DATA.meta?.generatedAt
    ? new Date(DATA.meta.generatedAt).toLocaleString()
    : "";
}

function renderStats() {
  const s = DATA.stats || {};
  const items = [
    { num: s.tools || 0, lbl: "Tools" },
    { num: s.agents || 0, lbl: "Agents" },
    { num: s.plugins || 0, lbl: "Plugins" },
    { num: s.skills || 0, lbl: "Skills" },
    { num: s.commitsLast2Months || 0, lbl: "Commits (last 2mo)" },
    { num: s.releases || 0, lbl: "Releases" },
  ];
  const grid = document.getElementById("stats-grid");
  items.forEach((item) => {
    const card = el("div", "stat");
    card.appendChild(el("div", "num", String(item.num)));
    card.appendChild(el("div", "lbl", item.lbl));
    grid.appendChild(card);
  });
}

