function renderTools() {
  document.getElementById("tools-intro").innerHTML = `
    <p>The agent receives tool schemas from the <code>TOOL_REGISTRY</code>. Each tool has a registration function that wires its JSON schema into pydantic-ai. Plugin tools and MCP tools are merged in at build time.</p>
    <p>Click a category below to filter. The "edit_file" compound tool auto-expands to create_file, replace_in_file, and delete_snippet for backward compatibility.</p>
  `;

  const tools = DATA.tools || [];
  const categories = [...new Set(tools.map((t) => t.category))].sort();
  const filters = document.getElementById("tool-filters");
  const grid = document.getElementById("tool-grid");

  let activeFilter = "all";

  function renderGrid() {
    grid.innerHTML = "";
    tools
      .filter((t) => activeFilter === "all" || t.category === activeFilter)
      .forEach((t) => {
        const item = el("div", "tool-item");
        const dot = el("span", "dot");
        dot.style.backgroundColor = TOOL_CATEGORY_COLORS[t.category] || "#888";
        item.appendChild(dot);
        item.appendChild(el("span", "", t.name));
        if (t.description) item.title = t.description;
        grid.appendChild(item);
      });
  }

  const allBtn = el("button", "chip active", "all");
  allBtn.addEventListener("click", () => {
    activeFilter = "all";
    filters.querySelectorAll(".chip").forEach((c) => c.classList.remove("active"));
    allBtn.classList.add("active");
    renderGrid();
  });
  filters.appendChild(allBtn);

  categories.forEach((cat) => {
    const btn = el("button", "chip", cat);
    btn.addEventListener("click", () => {
      activeFilter = cat;
      filters.querySelectorAll(".chip").forEach((c) => c.classList.remove("active"));
      btn.classList.add("active");
      renderGrid();
    });
    filters.appendChild(btn);
  });

  renderGrid();
}

