/* ------------------------------------------------------------------ */
// PLUGINS
/* ------------------------------------------------------------------ */

const HOOK_CATEGORIES = {
  Lifecycle: ["startup","shutdown","agent_run_start","agent_run_end","invoke_agent","agent_exception"],
  Model: ["model_select","load_model_config","load_models_config","load_model_descriptions","get_model_system_prompt","transform_model_messages"],
  Tools: ["register_tools","register_agent_tools","pre_tool_call","post_tool_call"],
  Agents: ["register_agents"],
  Skills: ["register_skills"],
  Security: ["file_permission","run_shell_command"],
  Commands: ["custom_command","custom_command_help"],
  CLI: ["register_cli_args","handle_cli_args"],
  Streaming: ["stream_event"],
  Prompts: ["load_prompt"],
  MCP: ["pre_mcp_autostart"],
};

function _categorizeHooks(hooks) {
  const cats = {};
  const used = new Set();
  for (const [cat, members] of Object.entries(HOOK_CATEGORIES)) {
    const matched = hooks.filter((h) => members.includes(h));
    if (matched.length) { cats[cat] = matched; matched.forEach((h) => used.add(h)); }
  }
  const other = hooks.filter((h) => !used.has(h));
  if (other.length) cats.Other = other;
  return cats;
}

const _pluginState = { sort: "name", tier: "all", use: "all", search: "", selected: null };

function _sortPlugins(list, sort) {
  const sorted = [...list];
  if (sort === "name") sorted.sort((a, b) => a.name.localeCompare(b.name));
  else if (sort === "tier") {
    const order = { builtin: 0, user: 1, project: 2 };
    sorted.sort((a, b) => (order[a.tier] ?? 3) - (order[b.tier] ?? 3) || a.name.localeCompare(b.name));
  } else if (sort === "hooks") sorted.sort((a, b) => (b.hooks?.length || 0) - (a.hooks?.length || 0));
  else if (sort === "files") sorted.sort((a, b) => (b.files?.length || 0) - (a.files?.length || 0));
  return sorted;
}

function _filterPlugins(list, state) {
  return list.filter((p) => {
    if (state.tier !== "all" && p.tier !== state.tier) return false;
    if (state.use !== "all") {
      const cats = _categorizeHooks(p.hooks || []);
      if (state.use === "cmd" && !p.hasCustomCommand) return false;
      if (state.use === "skill" && !p.hasSkill) return false;
      if (state.use === "readme" && !p.hasReadme) return false;
      if (state.use !== "cmd" && state.use !== "skill" && state.use !== "readme") {
        if (!cats[state.use]) return false;
      }
    }
    if (state.search) {
      const q = state.search.toLowerCase();
      const hay = (p.name + " " + (p.description || "") + " " + (p.hooks || []).join(" ")).toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
}

function _availableUses(plugins) {
  const uses = new Set();
  plugins.forEach((p) => {
    if (p.hasCustomCommand) uses.add("cmd");
    if (p.hasSkill) uses.add("skill");
    if (p.hasReadme) uses.add("readme");
    Object.keys(_categorizeHooks(p.hooks || [])).forEach((c) => uses.add(c));
  });
  return [...uses].sort();
}

const _USE_LABELS = {
  cmd: "/cmd", skill: "SKILL", readme: "README",
  Lifecycle: "Lifecycle", Model: "Model", Tools: "Tools", Agents: "Agents",
  Skills: "Skills", Security: "Security", Commands: "Commands", CLI: "CLI",
  Streaming: "Streaming", Prompts: "Prompts", MCP: "MCP", Other: "Other",
};

function renderPlugins() {
  document.getElementById("plugins-intro").innerHTML = `
    <p>Plugins are discovered from three tiers: builtin (<code>code_puppy/plugins/</code>), user (<code>~/.code_puppy/plugins/</code>), and project (<code>.code_puppy/plugins/</code>). Each is a directory containing <code>register_callbacks.py</code>.</p>
    <p>Project plugins are disabled by default until trusted via the <code>/plugins</code> TUI ceremony. Load order is builtin -> user -> project. Use the filters to sort and find plugins by type or use.</p>
  `;

  const allPlugins = DATA.plugins || [];
  const listEl = document.getElementById("plugins-list");
  const detailEl = document.getElementById("plugins-detail");
  const toolbarEl = document.getElementById("plugins-toolbar");
  if (!listEl || !detailEl || !toolbarEl) return;
  if (!allPlugins.length) {
    toolbarEl.innerHTML = "";
    detailEl.innerHTML = '<div class="md-empty">No plugins discovered.</div>';
    return;
  }

  const tiers = [...new Set(allPlugins.map((p) => p.tier).filter(Boolean))].sort();
  const uses = _availableUses(allPlugins);

  // --- Toolbar ---
  toolbarEl.innerHTML =
    `<input type="text" class="md-search" id="plugin-search" placeholder="Filter plugins..." value="${_pluginState.search}" />` +
    `<div class="md-sort-row"><label>Sort</label><select class="md-sort" id="plugin-sort">` +
    [["name","Name (A-Z)"],["tier","Tier"],["hooks","Hooks (most)"],["files","Files (most)"]].map(
      ([v,l]) => `<option value="${v}"${_pluginState.sort===v?" selected":""}>${l}</option>`
    ).join("") + `</select></div>` +
    `<div><div class="md-filter-group-label">Tier</div><div class="md-filter-group" id="plugin-tier-filters">` +
    ["all",...tiers].map((t) => `<button class="md-filter${_pluginState.tier===t?" active":""}" data-tier="${t}">${t==="all"?"All":t}</button>`).join("") +
    `</div></div>` +
    `<div><div class="md-filter-group-label">Use</div><div class="md-filter-group" id="plugin-use-filters">` +
    ["all",...uses].map((u) => `<button class="md-filter${_pluginState.use===u?" active":""}" data-use="${u}">${u==="all"?"All":(_USE_LABELS[u]||u)}</button>`).join("") +
    `</div></div>` +
    `<div class="md-count" id="plugin-count"></div>`;

  // Wire toolbar events
  document.getElementById("plugin-search").addEventListener("input", (e) => {
    _pluginState.search = e.target.value;
    _refreshPluginList(allPlugins, listEl, detailEl);
  });
  document.getElementById("plugin-sort").addEventListener("change", (e) => {
    _pluginState.sort = e.target.value;
    _refreshPluginList(allPlugins, listEl, detailEl);
  });
  toolbarEl.querySelectorAll("[data-tier]").forEach((btn) => {
    btn.addEventListener("click", () => {
      _pluginState.tier = btn.dataset.tier;
      toolbarEl.querySelectorAll("[data-tier]").forEach((b) => b.classList.remove("active"));
      btn.classList.add("active");
      _refreshPluginList(allPlugins, listEl, detailEl);
    });
  });
  toolbarEl.querySelectorAll("[data-use]").forEach((btn) => {
    btn.addEventListener("click", () => {
      _pluginState.use = btn.dataset.use;
      toolbarEl.querySelectorAll("[data-use]").forEach((b) => b.classList.remove("active"));
      btn.classList.add("active");
      _refreshPluginList(allPlugins, listEl, detailEl);
    });
  });

  _refreshPluginList(allPlugins, listEl, detailEl);
}

function _refreshPluginList(allPlugins, listEl, detailEl) {
  const filtered = _filterPlugins(allPlugins, _pluginState);
  const sorted = _sortPlugins(filtered, _pluginState.sort);

  const countEl = document.getElementById("plugin-count");
  if (countEl) countEl.textContent = `${filtered.length} of ${allPlugins.length} plugins`;

  listEl.innerHTML = "";
  if (!sorted.length) {
    listEl.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-muted);font-size:13px">No matches</div>';
    return;
  }

  // Preserve selection if still in list, else pick first
  const selected = _pluginState.selected && sorted.find((p) => p.name === _pluginState.selected) ? _pluginState.selected : sorted[0].name;
  _pluginState.selected = selected;

  sorted.forEach((p) => {
    const item = el("div", "md-item");
    item.appendChild(el("span", "", p.name));
    const meta = el("span", "", "");
    meta.style.cssText = "display:flex;gap:4px;align-items:center";
    if (p.tier) meta.appendChild(el("span", "md-tier", p.tier));
    const hookCount = (p.hooks || []).length;
    if (hookCount) {
      const hc = el("span", "md-tier", String(hookCount));
      hc.title = hookCount + " hooks";
      meta.appendChild(hc);
    }
    item.appendChild(meta);
    if (p.name === selected) item.classList.add("active");
    item.addEventListener("click", () => {
      _pluginState.selected = p.name;
      listEl.querySelectorAll(".md-item").forEach((n) => n.classList.remove("active"));
      item.classList.add("active");
      _renderPluginDetail(p, detailEl);
    });
    listEl.appendChild(item);
  });

  const detailPlugin = sorted.find((p) => p.name === selected);
  _renderPluginDetail(detailPlugin, detailEl);
}

function _renderPluginDetail(p, container) {
  const cats = _categorizeHooks(p.hooks || []);
  const hooksHtml = Object.entries(cats).map(([cat, hs]) =>
    `<div class="md-d-cat"><div class="md-d-cat-label">${cat}</div>` +
    `<div class="md-d-hooks">${hs.map((h) => `<span class="tag accent">${h}</span>`).join("")}</div></div>`
  ).join("");

  const filesHtml = (p.files || []).map((f) => {
    const name = typeof f === "string" ? f : f.name;
    const lines = typeof f === "object" ? f.lines : "";
    return `<div class="md-d-file"><span>${name}</span>${lines ? `<span class="lines">${lines} lines</span>` : ""}</div>`;
  }).join("");

  const flags = [
    { label: "Custom Command", y: p.hasCustomCommand },
    { label: "README", y: p.hasReadme },
    { label: "SKILL.md", y: p.hasSkill },
  ];

  container.innerHTML =
    `<div class="md-d-head"><h3>${p.name}</h3><div class="md-d-badges">` +
    `${p.tier ? `<span class="md-d-badge accent">${p.tier}</span>` : ""}` +
    `${p.hasCustomCommand ? `<span class="md-d-badge">/cmd</span>` : ""}` +
    `</div></div>` +
    `${p.description ? `<div class="md-d-desc">${p.description}</div>` : ""}` +
    `<div class="md-d-section"><h4>Capabilities</h4><div class="md-d-flags">` +
    flags.map((f) => `<div class="md-d-flag ${f.y ? "y" : "n"}">${f.y ? "yes" : "no"} ${f.label}</div>`).join("") +
    `</div></div>` +
    (hooksHtml ? `<div class="md-d-section"><h4>Hooks (${(p.hooks || []).length})</h4>${hooksHtml}</div>` : "") +
    (filesHtml ? `<div class="md-d-section"><h4>Files (${(p.files || []).length})</h4><div class="md-d-files">${filesHtml}</div>` : "");
}

/* ------------------------------------------------------------------ */
// SKILLS
/* ------------------------------------------------------------------ */

function renderSkills() {
  const section = document.getElementById("skills");
  if (!section) return;
  document.getElementById("skills-intro").innerHTML = `
    <p>Skills are deep, on-demand playbooks loaded via <code>activate_skill</code>. They live in plugin <code>SKILL.md</code> files and <code>~/.code_puppy/skills/</code>. Activate the right one before doing the work and the agent follows its full instructions.</p>
  `;
  const grid = document.getElementById("skills-grid");
  const skills = DATA.skills || [];
  if (!skills.length) {
    grid.appendChild(el("p", "", "No skills discovered. Add SKILL.md files under a plugin or ~/.code_puppy/skills/."));
    return;
  }
  skills.forEach((s) => {
    const card = el("div", "card");
    const head = el("div", "header");
    head.style.cssText = "display:flex;justify-content:space-between;align-items:baseline;gap:8px";
    head.appendChild(el("h3", "", s.name));
    head.appendChild(el("span", "badge", s.source));
    card.appendChild(head);
    if (s.description) card.appendChild(el("p", "", s.description));
    const meta = el("div", "meta-row");
    meta.appendChild(el("span", "tag", s.path));
    card.appendChild(meta);
    grid.appendChild(card);
  });
}

/* ------------------------------------------------------------------ */
// SDLC LIFECYCLE
/* ------------------------------------------------------------------ */

function renderLifecycle() {
  const section = document.getElementById("lifecycle");
  if (!section) return;
  document.getElementById("lifecycle-intro").innerHTML = `
    <p>How to take an idea to a tested, compliant, stable, secure — and genuinely <em>badass and beautiful</em> — deliverable using the whole pack. Each stage names the goal, the tools/agents/plugins to reach for, and the artifact you should walk away with.</p>
  `;
  const wrap = document.getElementById("sdlc-stages");
  (DATA.sdlc || []).forEach((s) => {
    const stage = el("div", "stage");
    const head = el("div", "head");
    head.appendChild(el("h3", "", s.stage));
    head.appendChild(el("p", "", s.goal));
    stage.appendChild(head);

    const cols = el("div", "cols");
    const left = el("div", "");
    left.appendChild(el("h4", "", "Reach for"));
    const ul = el("ul", "");
    (s.use || []).forEach((u) => ul.appendChild(el("li", "", u)));
    left.appendChild(ul);
    cols.appendChild(left);

    const right = el("div", "");
    right.appendChild(el("h4", "", "Walk away with"));
    right.appendChild(el("div", "output", s.output || ""));
    cols.appendChild(right);

    stage.appendChild(cols);
    wrap.appendChild(stage);
  });
}

/* ------------------------------------------------------------------ */
// COMMANDS
/* ------------------------------------------------------------------ */

function renderCommands() {
  document.getElementById("commands-intro").innerHTML = `
    <p>Slash commands start with <code>/</code> in the TUI. Console/meta commands start with <code>~</code>. Both are extensible: plugins can register custom slash commands, and markdown files in <code>.claude/commands/</code>, <code>.github/prompts/</code>, or <code>.agents/commands/</code> become custom commands.</p>
  `;

  const groups = document.getElementById("command-groups");
  [
    {
      title: "Agent switching",
      cmds: ["/agent", "/agent <name>", "/pin_model <agent> <model>"],
    },
    {
      title: "Context & memory",
      cmds: ["/save <name>", "/load <name>", "/truncate <N>", "/pop [N]", "/prune"],
    },
    {
      title: "Models",
      cmds: ["/model", "/add_model", "/models"],
    },
    {
      title: "System",
      cmds: ["/set <key> <value>", "/show", "/help", "/plugins", "/skills"],
    },
  ].forEach((g) => {
    const card = el("div", "card");
    card.appendChild(el("h3", "", g.title));
    const ul = el("ul", "");
    g.cmds.forEach((cmd) => {
      const li = el("li", "");
      li.appendChild(el("code", "", cmd));
      ul.appendChild(li);
    });
    card.appendChild(ul);
    groups.appendChild(card);
  });
}

/* ------------------------------------------------------------------ */
// SEARCH
/* ------------------------------------------------------------------ */

function initSearch() {
  const input = document.getElementById("global-search");
  input.addEventListener("input", (e) => {
    const term = e.target.value.trim().toLowerCase();
    const selectors = ".card, .agent-card, .tool-item, .tl-item, .release";
    if (!term) {
      document.querySelectorAll(selectors).forEach((el) => {
        el.style.display = "";
      });
      return;
    }
    document.querySelectorAll(selectors).forEach((el) => {
      const text = htmlToText(el.innerHTML).toLowerCase();
      el.style.display = text.includes(term) ? "" : "none";
    });
  });
}

/* ------------------------------------------------------------------ */
// BOOT
/* ------------------------------------------------------------------ */

function boot() {
  renderMeta();
  renderStats();
  renderOverview();
  renderCapabilities();
  renderArchitecture();
  renderTools();
  renderAgents();
  renderAgentCreator();
  renderHelios();
  renderPlugins();
  renderCommands();
  renderSkills();
  renderLifecycle();
  initSearch();
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", boot);
} else {
  boot();
}